-- =====================================================================
-- V7_14 — Extend TankerInbound from 7 → 16 canonical steps.
--
-- Full Pico Tanker Inbound flow per the customer spec (15 numbered ops):
--   1. Gate Pass (Front Gate)
--   2. Parking Bay In  (Parking)
--   3. Dispatch Front Office vehicle entry  (Dispatch)
--   4. QC Approval  (QC)
--   5. Parking Bay Out  (Parking)
--   6. Dispatch supervisor allocation  (Dispatch)
--   7. First Weighment (loaded)  (WeighmentOfficer)
--   8. Unloading process  (UnloadingSupervisor)
--   9. Second Weighment (empty)  (WeighmentOfficer)
--  10. Parking Bay In  (Parking)
--  11. Invoice qty vs unloading qty reconciliation  (Dispatch + Manager)
--  12. Parking Bay Out  (Parking)
--  13. Third Weighment (re-verify empty)  (WeighmentOfficer)
--  14. 2nd vs 3rd weight diff  (Manager)
--  15. Gate Pass Closure  (FrontGate)
-- =====================================================================

-- 1. Author the 2 new pages reconciliation + manager-weight-diff -----------
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:reconciliation','Invoice vs Unloading','Dispatch enters unloading qty + system flags differences for Manager.','M10.Dispatch','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:reconciliation');
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:manager-qty-approval','Manager Qty Approval','Manager approves/rejects qty difference.','M10.Dispatch','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:manager-qty-approval');
INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:manager-weight-approval','Manager Weight Diff Approval','Manager approves/rejects 2nd-vs-3rd weight difference.','M10.Dispatch','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:manager-weight-approval');

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Invoice vs Unloading","fields":[{"kind":"FormField","type":"number","name":"invoiceQty","label":"Invoice Qty (kg)"},{"kind":"FormField","type":"number","name":"unloadingQty","label":"Unloading Qty (W1-W2) kg"},{"kind":"FormField","type":"text","name":"deltaPct","label":"Delta % (auto)"},{"kind":"FormField","type":"select","name":"withinTolerance","label":"Within Tolerance?","options":[{"label":"Yes","value":"YES"},{"label":"No - send to Manager","value":"NO"}]},{"kind":"WorkflowActionButton","label":"Submit Reconciliation","action":"workflow.transition","variant":"primary"}]}]}', 'V7_14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:reconciliation' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Qty Approval","fields":[{"kind":"FormField","type":"text","name":"reason","label":"Reason / Justification"},{"kind":"FormField","type":"select","name":"status","label":"Decision","options":[{"label":"APPROVED","value":"APPROVED"},{"label":"REJECTED","value":"REJECTED"}]},{"kind":"WorkflowActionButton","label":"Submit Decision","action":"workflow.transition","variant":"primary"}]}]}', 'V7_14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:manager-qty-approval' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"kind":"layout","schemaVersion":2,"layout":[{"kind":"Section","title":"Weight Diff Approval","fields":[{"kind":"FormField","type":"text","name":"w2","label":"Weight 2 (empty after unload)"},{"kind":"FormField","type":"text","name":"w3","label":"Weight 3 (recheck empty)"},{"kind":"FormField","type":"text","name":"deltaKg","label":"Delta (kg)"},{"kind":"FormField","type":"text","name":"reason","label":"Reason"},{"kind":"FormField","type":"select","name":"status","label":"Decision","options":[{"label":"APPROVED","value":"APPROVED"},{"label":"REJECTED","value":"REJECTED"}]},{"kind":"WorkflowActionButton","label":"Submit Decision","action":"workflow.transition","variant":"primary"}]}]}', 'V7_14', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:manager-weight-approval' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code IN ('pico:reconciliation','pico:manager-qty-approval','pico:manager-weight-approval') AND current_version_id IS NULL;

-- 2. Replace TankerInbound body with full 16-step flow ---------------------
UPDATE workflow_definition SET body_json = '{"code":"M10.TankerInbound","version":1,"initialState":"DRAFT","states":[{"code":"DRAFT"},{"code":"GATE_PASS_CREATED","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN","assignedRole":"Dispatch"},{"code":"DISPATCH_QUEUED","assignedRole":"QC"},{"code":"QC_APPROVED","assignedRole":"ParkingSecurity"},{"code":"QC_REJECTED","terminal":true},{"code":"PARKING_OUT_AFTER_QC","assignedRole":"Dispatch"},{"code":"SUPERVISOR_ALLOCATED","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_LOADED","assignedRole":"UnloadingSupervisor"},{"code":"UNLOADING_DONE","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_EMPTY","assignedRole":"ParkingSecurity"},{"code":"PARKING_IN_AFTER_UNLOAD","assignedRole":"Dispatch"},{"code":"QTY_RECONCILED","assignedRole":"ParkingSecurity"},{"code":"QTY_PENDING_MANAGER","assignedRole":"Manager"},{"code":"PARKING_OUT_FINAL","assignedRole":"WeighmentOfficer"},{"code":"WEIGHMENT_RECHECK","assignedRole":"FrontGate"},{"code":"WEIGHT_DIFF_PENDING_MANAGER","assignedRole":"Manager"},{"code":"CLOSED","terminal":true},{"code":"REJECTED_BY_MANAGER","terminal":true}],"transitions":[{"from":"DRAFT","to":"GATE_PASS_CREATED","trigger":"page.submitted","pageCode":"pico:front-gate-create"},{"from":"GATE_PASS_CREATED","to":"PARKING_IN","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_IN","to":"DISPATCH_QUEUED","trigger":"page.submitted","pageCode":"pico:dispatch-vehicle-entry"},{"from":"DISPATCH_QUEUED","to":"QC_APPROVED","trigger":"page.submitted","pageCode":"pico:qc-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"DISPATCH_QUEUED","to":"QC_REJECTED","trigger":"page.submitted","pageCode":"pico:qc-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QC_APPROVED","to":"PARKING_OUT_AFTER_QC","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_OUT_AFTER_QC","to":"SUPERVISOR_ALLOCATED","trigger":"page.submitted","pageCode":"pico:dispatch-vehicle-entry"},{"from":"SUPERVISOR_ALLOCATED","to":"WEIGHMENT_LOADED","trigger":"page.submitted","pageCode":"pico:weighment-capture"},{"from":"WEIGHMENT_LOADED","to":"UNLOADING_DONE","trigger":"page.submitted","pageCode":"pico:supervisor-unloading"},{"from":"UNLOADING_DONE","to":"WEIGHMENT_EMPTY","trigger":"page.submitted","pageCode":"pico:weighment-capture"},{"from":"WEIGHMENT_EMPTY","to":"PARKING_IN_AFTER_UNLOAD","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_IN_AFTER_UNLOAD","to":"QTY_RECONCILED","trigger":"page.submitted","pageCode":"pico:reconciliation","guard":"#submitted[''withinTolerance''] == ''YES''"},{"from":"PARKING_IN_AFTER_UNLOAD","to":"QTY_PENDING_MANAGER","trigger":"page.submitted","pageCode":"pico:reconciliation","guard":"#submitted[''withinTolerance''] == ''NO''"},{"from":"QTY_PENDING_MANAGER","to":"QTY_RECONCILED","trigger":"page.submitted","pageCode":"pico:manager-qty-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"QTY_PENDING_MANAGER","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"pico:manager-qty-approval","guard":"#submitted[''status''] == ''REJECTED''"},{"from":"QTY_RECONCILED","to":"PARKING_OUT_FINAL","trigger":"page.submitted","pageCode":"pico:parking-scan"},{"from":"PARKING_OUT_FINAL","to":"WEIGHMENT_RECHECK","trigger":"page.submitted","pageCode":"pico:weighment-capture"},{"from":"WEIGHMENT_RECHECK","to":"CLOSED","trigger":"page.submitted","pageCode":"pico:gate-pass-closure","guard":"#submitted[''withinTolerance''] == ''YES''"},{"from":"WEIGHMENT_RECHECK","to":"WEIGHT_DIFF_PENDING_MANAGER","trigger":"page.submitted","pageCode":"pico:gate-pass-closure","guard":"#submitted[''withinTolerance''] == ''NO''"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"CLOSED","trigger":"page.submitted","pageCode":"pico:manager-weight-approval","guard":"#submitted[''status''] == ''APPROVED''"},{"from":"WEIGHT_DIFF_PENDING_MANAGER","to":"REJECTED_BY_MANAGER","trigger":"page.submitted","pageCode":"pico:manager-weight-approval","guard":"#submitted[''status''] == ''REJECTED''"}]}' WHERE tenant_id=1 AND code='M10.TankerInbound' AND version=1;
